import 'package:flutter/material.dart';
import '../../services/api_service.dart';

class SupervisorsScreen extends StatefulWidget { const SupervisorsScreen({super.key}); @override State<SupervisorsScreen> createState() => _SupervisorsScreenState(); }
class _SupervisorsScreenState extends State<SupervisorsScreen> {
  List supervisors=[]; bool loading=true;
  List<dynamic> list(dynamic x)=>x is List?List<dynamic>.from(x):(x is Map&&x['data'] is List?List<dynamic>.from(x['data']):[]);
  int id(dynamic x)=>int.tryParse('${x['id']}')??0;
